  const HTASK = ['becoming yourself', 'building your own ground', 'finding your own mind', 'coming to terms with your roots', 'making things for the joy of it', 'the daily upkeep of work and body', 'meeting the other person', 'the art of merging and letting go', 'the search for meaning', 'your vocation', 'belonging among friends', 'facing what is hidden'];
  const HJOY = { 0: 'mercury', 2: 'moon', 4: 'venus', 5: 'mars', 8: 'sun', 10: 'jupiter', 11: 'saturn' };
